// =================== ФИЛЬТРАЦИЯ ПО ИНВЕНТАРЮ ===================
function normalizedCatalogName(name) {
    return String(name ?? '').normalize('NFC').toLowerCase().replace(/ё/g, 'е').trim();
}

const catalogExercisesByName = new Map();
for (const exercise of EXERCISES_CATALOG) {
    for (const name of [exercise.name, ...(exercise.aliases || [])]) {
        const key = normalizedCatalogName(name);
        if (!catalogExercisesByName.has(key)) catalogExercisesByName.set(key, exercise);
    }
}

function findCatalogExercise(name) {
    return catalogExercisesByName.get(normalizedCatalogName(name));
}

function exerciseNameKey(name) {
    return normalizedCatalogName(findCatalogExercise(name)?.name ?? name);
}

function exerciseMatchesSearch(exercise, search) {
    const query = normalizedCatalogName(search);
    return [exercise.name, ...(exercise.aliases || [])].some(name =>
        normalizedCatalogName(name).includes(query));
}

